G1=$(group 'fwshift-outside' 'FWShift: for the interfaces of 0.0.0.0-10.9.255.255 10.11.0.0-10.19.255.255 10.20.1.0-10.29.255.255 10.30.1.0-10.39.255.255 10.41.0.0-192.168.0.255 192.168.2.0-255.255.255.255') || exit 1
