G4=$(group 'fwshift-dmz' 'FWShift: for the interfaces of 10.20.0.0-10.20.0.9 10.20.0.11-10.20.0.24 10.20.0.26-10.20.0.49 10.20.0.51-10.20.0.255') || exit 1
# attach fwshift-web-srv: 10.20.0.10
G5=$(group 'fwshift-web-srv' 'FWShift: for the interfaces of 10.20.0.10') || exit 1
# attach fwshift-mail-srv: 10.20.0.25
G6=$(group 'fwshift-mail-srv' 'FWShift: for the interfaces of 10.20.0.25') || exit 1
# attach fwshift-dmz-2: 10.20.0.50
